from typing import Any
from typing import TextIO
import csv
import io
import os

REQUIRED_COLUMNS = ('name', 'email')
MAX_ROWS = 10000
MAX_EMAIL_LENGTH = 254


# pcat: importers.users_csv.parse@v1
def import_users(source: str | TextIO, max_rows: int=MAX_ROWS) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    reader = csv.DictReader(io.StringIO(source) if isinstance(source, str) else source)
    header = [h.strip().lstrip('\ufeff').lower() for h in reader.fieldnames or []]
    missing = [c for c in REQUIRED_COLUMNS if c not in header]
    if missing:
        return ([], [{'row': 1, 'errors': [f"missing columns: {', '.join(missing)}"]}])
    reader.fieldnames = header
    valid, errors, seen = ([], [], set())
    for count, row in enumerate(reader, 1):
        if count > max_rows:
            stop = f'more than {max_rows} rows; stopped'
            errors.append({'row': reader.line_num, 'errors': [stop]})
            break
        name = (row.get('name') or '').strip()
        email = (row.get('email') or '').strip().lower()
        age_raw = (row.get('age') or '').strip()
        local, _, domain = email.partition('@')
        problems = [] if name else ['name is required']
        if None in row:
            problems.append('too many fields')
        if len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email or ('@' in domain) or ('.' not in domain.strip('.')):
            problems.append('email is invalid')
        elif email in seen:
            problems.append('duplicate email')
        if age_raw and (not (age_raw.isdigit() and int(age_raw) <= 150)):
            problems.append('age must be a whole number from 0 to 150')
        if problems:
            errors.append({'row': reader.line_num, 'errors': problems})
        else:
            seen.add(email)
            valid.append({'name': name, 'email': email, 'age': int(age_raw) if age_raw else None})
    return (valid, errors)


def excel_to_csv_text(file_obj: Any) -> str:
    """Convert the first worksheet of an .xlsx file to CSV text.

    Row numbers in the CSV match spreadsheet row numbers (header = row 1),
    because embedded line breaks in cells are flattened to spaces.
    """
    from openpyxl import load_workbook  # pip install openpyxl

    workbook = load_workbook(file_obj, read_only=True, data_only=True)
    try:
        sheet = workbook.worksheets[0]
        out = io.StringIO()
        writer = csv.writer(out)
        for cells in sheet.iter_rows(values_only=True):
            writer.writerow([
                '' if c is None else str(c).replace('\r', ' ').replace('\n', ' ')
                for c in cells
            ])
        return out.getvalue()
    finally:
        workbook.close()


def read_upload_as_csv_text(filename: str, data: bytes) -> str:
    """Return CSV text for an uploaded CSV or Excel (.xlsx) file's raw bytes."""
    ext = os.path.splitext(filename or '')[1].lower()
    if ext in ('.xlsx', '.xlsm'):
        return excel_to_csv_text(io.BytesIO(data))
    if ext == '.csv' or ext == '':
        return data.decode('utf-8-sig')
    raise ValueError(f'unsupported file type: {ext or "unknown"} (use .csv or .xlsx)')


def validate_user_upload(filename: str, data: bytes, max_rows: int=MAX_ROWS) -> dict[str, Any]:
    """Validate an uploaded spreadsheet of new users and report every bad row.

    Returns a dict:
      {
        'ok': bool,                 # True when no row is invalid
        'valid_count': int,
        'invalid_count': int,       # number of invalid rows
        'invalid_rows': [{'row': <spreadsheet row number>, 'errors': [reasons]}],
        'valid_users': [...],       # rows that passed, ready to import
        'file_error': str | None,   # set if the file itself could not be read
      }
    Validation never stops at the first bad row; all problems are collected.
    Row numbers count the header as row 1, so the first data row is row 2.
    """
    report: dict[str, Any] = {
        'ok': False, 'valid_count': 0, 'invalid_count': 0,
        'invalid_rows': [], 'valid_users': [], 'file_error': None,
    }
    try:
        text = read_upload_as_csv_text(filename, data)
    except ImportError:
        report['file_error'] = 'Excel support requires the openpyxl package'
        return report
    except (ValueError, UnicodeDecodeError) as exc:
        report['file_error'] = f'could not read file: {exc}'
        return report
    except Exception:
        report['file_error'] = 'could not read file: it may be corrupt or not a valid spreadsheet'
        return report

    valid_users, errors = import_users(text, max_rows=max_rows)
    report['valid_users'] = valid_users
    report['valid_count'] = len(valid_users)
    report['invalid_rows'] = sorted(errors, key=lambda e: e['row'])
    report['invalid_count'] = len(errors)
    report['ok'] = not errors
    return report


def format_upload_report(report: dict[str, Any]) -> str:
    """Render the report from validate_user_upload as plain text for staff."""
    if report.get('file_error'):
        return f"Upload failed: {report['file_error']}"
    lines = [f"{report['valid_count']} valid row(s), {report['invalid_count']} invalid row(s)."]
    for item in report['invalid_rows']:
        lines.append(f"Row {item['row']}: " + '; '.join(item['errors']))
    return '\n'.join(lines)

